import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

export const AuthProvider = ({ children }) => {
  // یوزرهای پیش‌فرض (روت و یه ادمین معمولی)
  const defaultUsers = [
    { id: 1, username: 'root', password: 'darklight2024', role: 'root', name: 'Super Admin' },
    { id: 2, username: 'admin', password: 'admin123', role: 'admin', name: 'Admin User' },
  ];

  const [users, setUsers] = useState(() => {
    const saved = localStorage.getItem('dl-users');
    return saved ? JSON.parse(saved) : defaultUsers;
  });

  const [currentUser, setCurrentUser] = useState(() => {
    const saved = localStorage.getItem('dl-current-user');
    return saved ? JSON.parse(saved) : null;
  });

  useEffect(() => {
    localStorage.setItem('dl-users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('dl-current-user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('dl-current-user');
    }
  }, [currentUser]);

  const login = (username, password) => {
    const user = users.find(u => u.username === username && u.password === password);
    if (user) {
      setCurrentUser(user);
      return { success: true, user };
    }
    return { success: false, message: 'نام کاربری یا رمز عبور اشتباه است' };
  };

  const logout = () => {
    setCurrentUser(null);
  };

  const addUser = (newUser) => {
    // فقط روت می‌تونه یوزر اضافه کنه
    if (currentUser?.role !== 'root') {
      return { success: false, message: 'فقط سوپر ادمین می‌تواند کاربر جدید اضافه کند' };
    }

    // چک کن تکراری نباشه
    if (users.find(u => u.username === newUser.username)) {
      return { success: false, message: 'این نام کاربری قبلاً ثبت شده است' };
    }

    const user = {
      id: Date.now(),
      ...newUser,
      role: 'admin',
    };

    setUsers([...users, user]);
    return { success: true, message: 'کاربر با موفقیت اضافه شد' };
  };

  const deleteUser = (userId) => {
    if (currentUser?.role !== 'root') {
      return { success: false, message: 'فقط سوپر ادمین می‌تواند کاربر حذف کند' };
    }
    setUsers(users.filter(u => u.id !== userId));
    return { success: true, message: 'کاربر حذف شد' };
  };

  const getUsers = () => {
    if (currentUser?.role !== 'root') return [];
    return users.filter(u => u.role !== 'root');
  };

  return (
    <AuthContext.Provider value={{ currentUser, users, login, logout, addUser, deleteUser, getUsers }}>
      {children}
    </AuthContext.Provider>
  );
};
